let db=loadDB(), route=location.hash.slice(1)||'home', lang=localStorage.getItem('ks.lang')||'English', searchState={},activeUser=null;
function loadDB(){return structuredClone(seed)}
function save(){if(KaushalApi.connected&&currentUser())KaushalApi.sync(db).catch(e=>toast(`Could not save to the server: ${e.message}`))}
function currentUser(){const actor=KaushalApi.user||activeUser;if(actor){return db.users.find(u=>u.id&&u.id===actor.id)||actor}return null}
function esc(x=''){return String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]))}
function toast(msg){const el=document.getElementById('toast');el.className='toast show';el.textContent=msg;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>el.className='toast',2600)}
function go(r){location.hash=r}
