const navItems=[['home','Home'],['jobs','Find Jobs'],['courses','Courses'],['apprenticeships','Apprenticeships'],['employers','Employers'],['centres','Training Centres'],['drives','Rozgar Melas'],['schemes','Government Schemes']];
function header(){const u=currentUser();return `<header class="topbar"><a class="brand" href="#home"><span class="logo">K</span><span>KaushalSetu<small>SKILLS TO OPPORTUNITY</small></span></a><nav class="nav" id="main-nav">${navItems.map(([r,n])=>`<a class="${route===r?'active':''}" href="#${r}">${T(n)}</a>`).join('')}<a href="#about">${T('About Us')}</a></nav><div class="right-nav"><select class="lang" aria-label="Choose language" onchange="setLanguage(this.value)">${['English','Hindi','Kannada','Telugu','Tamil'].map(x=>`<option ${lang===x?'selected':''}>${x}</option>`).join('')}</select>${u?`<a class="btn btn-outline btn-sm" href="#dashboard">${esc(u.name.split(' ')[0])} · Dashboard</a><button class="btn btn-primary btn-sm" onclick="logout()">Sign out</button>`:`<a class="btn btn-outline btn-sm" href="#login">${T('Login')}</a>`}<button class="menu-toggle" onclick="document.getElementById('main-nav').classList.toggle('open')" aria-label="Open menu">☰</button></div></header>`}
function footer(){return `<footer class="footer"><div class="footer-inner"><div><div class="brand" style="color:white"><span class="logo">K</span><span>KaushalSetu<small>SKILLS TO OPPORTUNITY</small></span></div><p class="tiny" style="max-width:330px;color:#b9c8d5;line-height:1.7">A local-first demonstration portal connecting Karnataka's talent, employers and training partners.</p><small>Academic mini-project · Demo data only</small></div><div><strong>Explore</strong><p class="tiny"><a href="#jobs">Find Jobs</a> · <a href="#courses">Courses</a> · <a href="#drives">Rozgar Melas</a></p><p class="tiny"><a href="#schemes">Government schemes</a> · <a href="#assistant">AI Career Assistant</a></p></div><div><strong>Project</strong><p class="tiny">Dr. T. Thimmaiah Institute of Technology<br>Department of CSE (AI & ML)<br>Visvesvaraya Technological University</p></div><div><strong>Contact</strong><p class="tiny">Demo portal · Kolar, Karnataka<br><a href="#contact">Contact us</a></p></div></div></footer>`}
function pageTitle(title,sub){return `<div class="page-title"><div><h1>${title}</h1><p>${sub}</p></div></div>`}
function stat(n,label){return `<div class="stat-card"><div class="num">${n}</div><small>${label}</small></div>`}
function home(){return `<main><section class="hero"><div class="hero-inner"><div><div class="eyebrow">LOCAL OPPORTUNITY · KARNATAKA</div><h1>${T('Discover Skills. Find Opportunities. Build Your Future.')}</h1><p>A centralized platform connecting local talent, employers, training institutes and government skill development programmes.</p><div class="hero-actions"><a class="btn btn-primary" href="#jobs">Find Jobs&nbsp; →</a><a class="btn btn-outline" href="#courses">Explore Courses</a><a class="btn btn-outline" href="#login?role=employer">Register as Employer</a><a class="btn btn-outline" href="#login?role=centre">Register as Training Centre</a></div></div><aside class="hero-art"><span class="pill" style="background:#ffffff1c;color:#cce8fb">KARNATAKA · DEMO PORTAL</span><div class="big">${db.jobs.length+db.jobsPosted.length}</div><div class="muted">sample local opportunities</div><div style="height:20px"></div><div class="mini-row"><span>New this week</span><strong>12 opportunities</strong></div><div class="mini-row"><span>Districts covered</span><strong>5 districts</strong></div><div class="mini-row"><span>Course seats open</span><strong>${db.courses.reduce((n,c)=>n+c.seats,0)} seats</strong></div></aside></div></section><div class="wrap" style="padding-top:0"><div class="stats">${stat('1,240+','Sample job seekers')}${stat('86','Sample employers')}${stat('42','Training programmes')}${stat('5','Karnataka districts')}</div></div><section class="wrap section-gap"><div class="section-head"><div><h2>Latest opportunities</h2><p>Roles from employers across Karnataka · sample listings</p></div><a class="link" href="#jobs">Browse all jobs →</a></div><div class="grid grid-3">${[...db.jobsPosted,...db.jobs].slice(0,3).map(jobCard).join('')}</div></section><section class="wrap section-gap" style="padding-top:4px"><div class="section-head"><div><h2>Build in-demand skills</h2><p>Practical short courses from nearby training partners</p></div><a class="link" href="#courses">Explore all courses →</a></div><div class="grid grid-3">${[...db.coursesPublished,...db.courses].slice(0,3).map(courseCard).join('')}</div></section><section class="category-band"><div class="wrap"><div class="section-head"><div><h2>Trusted local partners</h2><p>Sample employer directory</p></div></div><div class="employer-strip">${db.employers.map((x,i)=>`<div class="employer"><span class="company-mark">${esc(x.name.slice(0,1))}</span><span>${esc(x.name)}<small class="sub" style="display:block;font-weight:400;margin-top:4px">${esc(x.district)}</small></span></div>`).join('')}</div></div></section><section class="wrap"><div class="section-head"><div><h2>Upcoming Rozgar Melas</h2><p>Meet local employers and discover opportunities</p></div><a class="link" href="#drives">See all drives →</a></div><div class="grid grid-3">${db.drives.map(driveCard).join('')}</div></section><section class="wrap" style="padding-top:0"><div class="section-head"><div><h2>Government skill development</h2><p>Explore official information and discover ways to participate</p></div><a class="link" href="#schemes">View schemes →</a></div><div class="grid grid-3">${schemeCards().slice(0,3).join('')}</div></section><section class="category-band"><div class="wrap"><div class="section-head"><div><h2>How KaushalSetu works</h2><p>One local platform, four connected journeys</p></div></div><div class="steps">${[['01','Create your profile','Share your education, skills and career goals.'],['02','Discover opportunities','Find a local job, apprenticeship or training course.'],['03','Apply and build skills','Apply with one profile and keep learning.'],['04','Track your progress','Follow applications, enrolments and certificates.']].map(([n,t,p])=>`<div class="step"><span class="step-num">${n}</span><h3>${t}</h3><p>${p}</p></div>`).join('')}</div></div></section><section class="wrap"><div class="section-head"><div><h2>Community voices</h2><p>Illustrative testimonials · demo content</p></div></div><div class="grid grid-3">${[['“The nearby course helped me find a clear path into data work.”','Demo learner · Mysuru'],['“We reached skilled local candidates in one place.”','Demo employer · Kolar'],['“Our training batches are easier to share with local youth.”','Demo training partner · Tumakuru']].map(([q,a])=>`<div class="quote">${q}<div class="rule"></div><strong>${a}</strong></div>`).join('')}</div></section></main>`}
function jobCard(j){const score=scoreJob(j,currentUser());return `<article class="job-card"><div class="card-top"><span class="company-mark">${esc(j.company.slice(0,1))}</span><span class="pill">${esc(j.category)}</span></div><h3>${esc(j.title)}</h3><div class="sub">${esc(j.company)} · ${esc(j.district)}</div><div class="chips">${j.skills.slice(0,3).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><div class="row sub"><span>${esc(j.salary)}</span><span>${esc(j.experience)}</span></div><div class="rule"></div><div class="row"><span class="tiny muted">${esc(j.posted||'Just posted')}${score!==null?` · <b style="color:var(--green)">${score}% match</b>`:''}</span><button class="btn btn-primary btn-sm" onclick="jobDetail('${esc(j.id)}')">View & apply</button></div></article>`}
function courseCard(c){return `<article class="course-card"><div class="card-top"><span class="company-mark">✦</span><span class="pill green">${esc(c.mode)}</span></div><h3>${esc(c.name)}</h3><div class="sub">${esc(c.centre)} · ${esc(c.district)}</div><div class="chips">${c.skills.slice(0,3).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><div class="row sub"><span>${esc(c.duration)} · ${esc(c.fees)}</span><span>${c.seats} seats</span></div><div class="rule"></div><div class="row"><span class="tiny muted">${esc(c.eligibility)}</span><button class="btn btn-primary btn-sm" onclick="enroll('${esc(c.id)}')">Enroll</button></div></article>`}
function driveCard(d){return `<article class="drive"><div class="row"><span class="pill orange">${esc(d.date)}</span><span class="tiny muted">${esc(d.district)}</span></div><h3 style="font:700 15px Manrope;color:var(--navy);margin:12px 0 5px">${esc(d.name)}</h3><p class="sub">${esc(d.hosts)}</p><a href="#drives" class="link">Drive details →</a></article>`}
function schemeCards(){return [['Skill India Digital Hub','Explore digital learning and career pathways through the national platform.','https://www.skillindiadigital.gov.in/'],['PMKVY','Learn about Pradhan Mantri Kaushal Vikas Yojana and short-term skill training.','https://www.pmkvyofficial.org/'],['NSDC','Discover the National Skill Development Corporation and its initiatives.','https://nsdcindia.org/'],['ITI programmes','Explore vocational trades and admissions through local ITIs.','https://dgt.gov.in/'],['Apprenticeship India','Find apprenticeship information and opportunities.','https://www.apprenticeshipindia.gov.in/'],['e-Shram','Learn about the national database for unorganised workers.','https://eshram.gov.in/']].map(([n,p,u])=>`<article class="scheme"><span class="icon">↗</span><div><h3>${n}</h3><p>${p}</p><a class="link" target="_blank" rel="noreferrer" href="${u}">Visit official information ↗</a></div></article>`)}
function jobsPage(){let all=[...db.jobsPosted,...db.jobs],f=searchState;const filt=all.filter(j=>(!f.q||`${j.title} ${j.company} ${j.skills.join(' ')}`.toLowerCase().includes(f.q.toLowerCase()))&&(!f.district||j.district===f.district)&&(!f.category||j.category===f.category)&&(!f.experience||j.experience===f.experience)&&(!f.salary||j.max>=Number(f.salary)));return `${pageTitle('Find local jobs','Search sample vacancies by district, role and experience. Matching scores are a prototype estimate.') }<main class="wrap"><div class="toolbar"><input class="field" placeholder="Job title, company or skill" value="${esc(f.q||'')}" oninput="searchState.q=this.value;refreshJobs()"><select class="field" onchange="searchState.district=this.value;refreshJobs()"><option value="">All districts</option>${districtOptions(f.district)}</select><select class="field" onchange="searchState.category=this.value;refreshJobs()"><option value="">All categories</option>${[...new Set(all.map(j=>j.category))].map(x=>`<option ${f.category===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select class="field" onchange="searchState.experience=this.value;refreshJobs()"><option value="">Any experience</option><option ${f.experience==='Fresher'?'selected':''}>Fresher</option><option ${f.experience==='1–3 years'?'selected':''}>1–3 years</option></select><select class="field" onchange="searchState.salary=this.value;refreshJobs()"><option value="">Any salary</option><option value="3" ${f.salary==='3'?'selected':''}>₹3 LPA+</option><option value="4" ${f.salary==='4'?'selected':''}>₹4 LPA+</option></select><button class="btn btn-outline btn-sm" onclick="searchState={};go('jobs')">Clear</button></div><div class="row" style="margin-bottom:15px"><span class="sub">${filt.length} opportunities · sample listings</span><span class="tiny muted">Match score = 60% skills + 25% experience + 15% education</span></div><div class="grid grid-3">${filt.length?filt.map(jobCard).join(''):'<div class="empty">No matching jobs. Try changing your filters.</div>'}</div></main>`}
function districtOptions(value=''){return ['Bengaluru Urban','Kolar','Tumakuru','Mysuru','Chikkaballapur'].map(x=>`<option ${value===x?'selected':''}>${x}</option>`).join('')}
function coursesPage(){const all=[...db.coursesPublished,...db.courses];return `${pageTitle('Skill development courses','Find practical training near you. Course and accreditation details are sample records.') }<main class="wrap"><div class="toolbar"><input id="course-q" class="field" placeholder="Search course or skill" oninput="filterCards('course-q','.course-card')"><select class="field" onchange="filterDistrictCards(this.value,'.course-card')"><option value="">All districts</option>${districtOptions()}</select><span class="pill green">Short-term courses · ITI · Hybrid learning</span></div><div class="grid grid-3">${all.map(courseCard).join('')}</div></main>`}
function apprenticeshipsPage(){return `${pageTitle('Apprenticeships','Build workplace experience with local apprenticeship opportunities. Sample listings; stipend details are illustrative.') }<main class="wrap"><div class="grid grid-2">${db.apprenticeships.map(a=>`<article class="job-card"><div class="row"><span class="pill orange">${esc(a.duration)}</span><span class="sub">${esc(a.district)}</span></div><h3>${esc(a.title)}</h3><div class="sub">${esc(a.company)}</div><div class="rule"></div><div class="row sub"><span>Stipend: ${esc(a.stipend)}</span><span>Eligibility: ${esc(a.eligibility)}</span></div><div class="chips">${a.skills.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><button class="btn btn-primary btn-sm" onclick="applyApprentice('${a.id}')">Apply for apprenticeship</button></article>`).join('')}</div><p class="tiny muted" style="margin-top:18px">Official apprenticeship registration and stipend verification require Apprenticeship India integration.</p></main>`}
function employersPage(){return `${pageTitle('For employers','Post vacancies, discover local talent and take part in district recruitment drives.') }<main class="wrap"><div class="grid grid-2"><div class="panel"><h2>Reach skilled local candidates</h2><p class="muted" style="font-size:13px;line-height:1.7">Create a free employer account to list roles, review applications, shortlist candidates and connect with nearby training centres.</p><a class="btn btn-primary" href="#login?role=employer">Register as employer</a> <a class="btn btn-outline" href="#dashboard">Employer sign in</a></div><div class="panel"><h2>Local recruitment drives</h2><p class="muted" style="font-size:13px;line-height:1.7">Meet candidates face to face through sample Rozgar Mela listings across Mysuru, Kolar and Tumakuru.</p><a class="link" href="#drives">Browse upcoming drives →</a></div></div><div class="section-head section-gap"><div><h2>Employer directory</h2><p>Sample employer profiles</p></div></div><div class="employer-strip">${db.employers.map(x=>`<div class="employer"><span class="company-mark">${esc(x.name[0])}</span><span>${esc(x.name)}<small class="sub" style="display:block">${esc(x.sector)} · ${esc(x.district)}</small></span></div>`).join('')}</div></main>`}
function centresPage(){return `${pageTitle('Training centres','Discover verified-looking sample institutes and local training programmes. Listings are illustrative.') }<main class="wrap"><div class="panel"><h2>Partner with local employers</h2><p class="muted" style="font-size:13px;line-height:1.7">Training centres can publish courses, manage student enrolments, track attendance and record placements through a dedicated dashboard.</p><a href="#login?role=centre" class="btn btn-primary">Register as training centre</a></div><div class="section-head section-gap"><div><h2>Nearby training centres</h2><p>Sample partner directory · Karnataka</p></div></div><div class="grid grid-3">${db.centres.map(c=>`<article class="course-card"><div class="company-mark">⌂</div><h3>${esc(c.name)}</h3><p class="sub">${esc(c.district)} district · ${c.courses} sample programmes</p><a class="link" href="#courses">View available courses →</a></article>`).join('')}</div></main>`}
function drivesPage(){return `${pageTitle('Rozgar Melas','Local recruitment drives and career fairs. Dates and hosts shown are sample demonstration data.') }<main class="wrap"><div class="grid grid-3">${db.drives.map(driveCard).join('')}</div><div class="panel" style="margin-top:22px"><h2>Interested in hosting a drive?</h2><p class="muted" style="font-size:13px">Employers and centres can coordinate with district employment offices. This prototype does not submit requests to government offices.</p><a class="btn btn-outline" href="#login?role=employer">Continue as employer</a></div></main>`}
function schemesPage(){return `${pageTitle('Government skill development schemes','Official information links to public programmes. This prototype has no government API or beneficiary verification.') }<main class="wrap"><div class="notice">KaushalSetu is an academic demonstration. It is not an official government portal and does not verify eligibility, enrolment, stipends or benefits.</div><div class="grid grid-2">${schemeCards().join('')}</div></main>`}
function aboutPage(){return `${pageTitle('About KaushalSetu','A local skill development and employment information portal concept for Karnataka.') }<main class="wrap"><div class="grid grid-2"><div class="panel"><h2>Our purpose</h2><p class="muted" style="line-height:1.8;font-size:14px">KaushalSetu brings job seekers, employers, training centres and administration into one local-first experience. Young people can discover jobs, build practical skills, enroll in courses and track their career progress.</p><p class="tiny muted">Academic mini-project · Dr. T. Thimmaiah Institute of Technology · CSE (AI & ML) · VTU</p></div><div class="panel"><h2>Four connected roles</h2>${[['Job seekers','Build a profile, find matches and track applications.'],['Employers','Post vacancies and manage local candidates.'],['Training centres','Publish courses and follow learner progress.'],['Administration','Review portal activity and district level trends.']].map(([a,b])=>`<p><strong>${a}</strong><br><span class="sub">${b}</span></p>`).join('')}</div></div></main>`}
function contactPage(){return `${pageTitle('Contact us','Questions about this academic demonstration? Send a local message.') }<main class="wrap"><div class="panel" style="max-width:650px;margin:auto"><form onsubmit="event.preventDefault();toast('Message saved in this demo session.');this.reset()"><div class="form-grid"><div class="form-group"><label>Your name</label><input class="field" required></div><div class="form-group"><label>Email address</label><input class="field" type="email" required></div><div class="form-group full"><label>Message</label><textarea class="field" rows="5" required></textarea></div><div class="form-group full"><button class="btn btn-primary">Send message</button><span class="tiny muted">Demo form · no email is sent</span></div></div></form></div></main>`}
function loginPage(){const preferredRole=new URLSearchParams(location.hash.split('?')[1]||'').get('role');return `${pageTitle('Welcome to KaushalSetu','Sign in to continue, or create a role-based account.') }<main class="wrap"><div class="grid grid-2" style="max-width:900px;margin:auto"><div class="panel"><h2>Sign in</h2><form onsubmit="event.preventDefault();login(this)"><div class="form-group"><label>Email</label><input class="field" type="email" name="email" required placeholder="you@example.com"></div><div class="form-group" style="margin:14px 0"><label>Password</label><input class="field" type="password" name="password" required></div><button class="btn btn-primary">Sign in</button></form><div class="rule"></div><strong class="tiny">Seeded demo accounts · password <code>Demo@123</code></strong><div class="tiny muted" style="line-height:1.8;margin-top:8px">Job seeker: seeker@demo.in<br>Employer: employer@demo.in<br>Training centre: centre@demo.in<br>Administration: admin@demo.in</div></div><div class="panel"><h2>Create an account</h2><form onsubmit="event.preventDefault();register(this)"><div class="form-group"><label>Full name</label><input class="field" name="name" required minlength="2"></div><div class="form-group" style="margin-top:12px"><label>Email</label><input class="field" name="email" type="email" required></div><div class="form-grid" style="margin-top:12px"><div class="form-group"><label>Password (12+ characters)</label><input class="field" name="password" type="password" minlength="12" required></div><div class="form-group"><label>Account role</label><select class="field" name="role" required><option value="seeker" ${preferredRole==='seeker'?'selected':''}>Job seeker</option><option value="employer" ${preferredRole==='employer'?'selected':''}>Employer</option><option value="centre" ${preferredRole==='centre'?'selected':''}>Training centre</option></select></div><div class="form-group"><label>District</label><select class="field" name="district">${districtOptions()}</select></div><div class="form-group"><label>Phone (optional)</label><input class="field" name="phone" inputmode="tel" pattern="[0-9+ -]{8,15}"></div></div><p class="tiny muted">Account credentials are handled by the backend. Do not reuse a personal password in this academic demo.</p><button class="btn btn-dark">Create account</button></form></div></div></main>`}
function assistantPage(){return `${pageTitle('AI Career Assistant','Prototype chat responses powered by local rules. No external AI model is connected.') }<main class="wrap"><div class="panel chat" style="max-width:760px;margin:auto"><div class="notice">Mock response system · Your messages are not sent to an AI service. Responses are generated from local demo logic.</div><div class="chat-log" id="chat-log"><div class="bubble">Namaste! I can help you explore career paths, prepare for interviews, find courses or understand job applications. What would you like help with?</div></div><div class="chat-form"><input class="field" id="chat-input" placeholder="Ask about careers, interviews, skills…" onkeydown="if(event.key==='Enter')sendChat()"><button class="btn btn-primary" onclick="sendChat()">Send</button></div><div class="chips"><button class="chip" onclick="quickChat('How can I prepare for an interview?')">Interview preparation</button><button class="chip" onclick="quickChat('What skills should I learn?')">Skill recommendations</button><button class="chip" onclick="quickChat('How do I apply for a job?')">Application help</button></div></div></main>`}
function dashboard(){const u=currentUser();if(!u)return loginPage();if(u.role==='seeker')return seekerDash(u);if(u.role==='employer')return employerDash(u);if(u.role==='centre')return centreDash(u);return adminDash(u)}
function adminReviewPanel(){const jobs=db.jobs.filter(x=>x.status==='pending'),courses=db.courses.filter(x=>x.status==='pending');if(!jobs.length&&!courses.length)return '';return `<div class="panel"><h2>Pending listing approvals</h2>${[...jobs.map(x=>({type:'job',id:x.id,title:x.title,district:x.district})),...courses.map(x=>({type:'course',id:x.id,title:x.name,district:x.district}))].map(x=>`<div class="row" style="padding:10px 0;border-bottom:1px solid var(--line)"><span><b>${esc(x.title)}</b><small class="sub" style="display:block">${esc(x.type)} · ${esc(x.district)}</small></span><span><button class="btn btn-primary btn-sm" onclick="reviewListing('${x.type}','${esc(x.id)}','published')">Approve</button> <button class="btn btn-outline btn-sm" onclick="reviewListing('${x.type}','${esc(x.id)}','rejected')">Reject</button></span></div>`).join('')}</div>`}
async function reviewListing(type,id,decision){try{await KaushalApi.reviewListing(type,id,decision);const list=type==='job'?db.jobs:db.courses,record=list.find(x=>x.id===id);if(record)record.status=decision;toast(`${type} listing ${decision}.`);render()}catch(e){toast(e.message)}}
function dashShell(u,content,active='Overview'){const menus=['Overview',...(u.role==='seeker'?['My profile','Applications','Apprenticeships','My learning','Skill assessment','Certificates']:u.role==='employer'?['Company profile','Job postings','Applications','Candidates','Recruitment drives']:u.role==='centre'?['Institute profile','Courses','Enrollments','Attendance & performance','Placements']:['People & partners','Approvals','Jobs & courses','Apprenticeships','Analytics & reports','Schemes & benefits'])];return `<div class="mobile-side">${menus.map(n=>`<a href="#dashboard" onclick="showDashSection('${n}')">${n}</a>`).join('')}</div><div class="dashboard"><aside class="sidebar"><div class="side-user"><strong>${esc(u.name)}</strong><span>${roleName(u.role)} · ${esc(u.district||'Karnataka')}</span></div>${menus.map((n,i)=>`<a class="side-link ${active===n?'active':''}" href="#dashboard" onclick="showDashSection('${n}')"><span>${['◫','◉','▣','✓','↗','◎','⌂'][i%7]}</span>${n}</a>`).join('')}<a class="side-link" href="#assistant">✦ &nbsp;AI Career Assistant</a></aside><main class="dash-main">${u.role==='admin'?adminReviewPanel():''}${content}</main></div>`}
function roleName(r){return {seeker:'Job seeker',employer:'Employer',centre:'Training centre',admin:'Administration'}[r]}
function metric(label,value){return `<div class="metric"><span>${label}</span><strong>${value}</strong></div>`}
function seekerDash(u){const apps=u.applications||[],enrs=u.enrollments||[],matches=[...db.jobsPosted,...db.jobs].map(j=>({j,s:scoreJob(j,u)})).sort((a,b)=>b.s-a.s).slice(0,3);return dashShell(u,`<div class="dash-welcome"><div><h1>Good day, ${esc(u.name.split(' ')[0])} 👋</h1><p>Here’s your career journey at a glance.</p></div><button class="btn btn-primary" onclick="editProfile()">Edit profile</button></div><div class="metric-grid">${metric('Profile completeness',profilePct(u)+'%')}${metric('Applications',apps.length)}${metric('Courses enrolled',enrs.length)}${metric('Top skill match',matches[0]?.s+'%'||'—')}</div><div class="dash-grid"><div><div class="panel"><h2>Recommended for you <span class="tiny muted">· prototype matching</span></h2>${matches.map(({j,s})=>`<div class="match"><div class="row"><strong>${esc(j.title)}</strong><span class="pill green">${s}% match</span></div><div class="sub">${esc(j.company)} · ${esc(j.district)} · ${esc(j.salary)}</div><div class="match-meter"><i style="width:${s}%"></i></div><div class="row"><span class="tiny muted">Skills + experience + education</span><button class="btn btn-soft btn-sm" onclick="jobDetail('${j.id}')">View job</button></div></div>`).join('')}</div><div class="panel"><h2>Recent applications</h2>${apps.length?`<div class="table-wrap"><table><thead><tr><th>Role</th><th>Company</th><th>Status</th></tr></thead><tbody>${apps.slice(-4).map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.company)}</td><td>${statusPill(a.status)}</td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Your applications will appear here.<br><a class="link" href="#jobs">Find a job →</a></div>'}</div></div><div><div class="panel"><h2>My skills</h2><div class="chips">${(u.skills||[]).map(s=>`<span class="chip">${esc(s)}</span>`).join('')||'<span class="sub">Add skills to improve your matches.</span>'}</div><button class="btn btn-outline btn-sm" onclick="editProfile()">Update profile</button></div><div class="panel"><h2>Career tools</h2><p><a class="link" href="#assistant">✦ Ask AI Career Assistant →</a></p><p><a class="link" href="#courses">▣ Explore skill courses →</a></p><p><a class="link" href="#apprenticeships">↗ Apprenticeships →</a></p><p><button class="link" style="border:0;background:none;padding:0" onclick="skillGap()">◎ Run skill gap analysis →</button></p></div></div></div>`)}
function profilePct(u){return Math.min(100,30+(u.education?20:0)+(u.phone?10:0)+((u.skills||[]).length?20:0)+(u.resume?20:0))}
function statusPill(s){return `<span class="pill ${s==='Selected'||s==='Shortlisted'?'green':s==='Rejected'?'red':s==='Under Review'?'orange':''}">${esc(s)}</span>`}
function employerDash(u){const own=db.jobsPosted.filter(j=>j.owner===u.email),apps=allApplications().filter(a=>own.some(j=>j.id===a.jobId));return dashShell(u,`<div class="dash-welcome"><div><h1>Employer dashboard</h1><p>Manage your vacancies and local candidate pipeline.</p></div><button class="btn btn-primary" onclick="jobForm()">＋ Post a free job</button></div><div class="metric-grid">${metric('Active vacancies',own.length)}${metric('Applications received',apps.length)}${metric('Candidates shortlisted',apps.filter(a=>a.status==='Shortlisted').length)}${metric('Profile views',Math.max(12,own.length*24))}</div><div class="dash-grid"><div><div class="panel"><h2>Your job postings</h2>${own.length?`<div class="table-wrap"><table><thead><tr><th>Role</th><th>District</th><th>Applications</th><th>Action</th></tr></thead><tbody>${own.map(j=>`<tr><td>${esc(j.title)}</td><td>${esc(j.district)}</td><td>${allApplications().filter(a=>a.jobId===j.id).length}</td><td><button class="btn btn-outline btn-sm" onclick="editJob('${j.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">No vacancies yet. Post your first local job.</div>'}</div><div class="panel"><h2>Received applications</h2>${apps.length?`<div class="table-wrap"><table><thead><tr><th>Candidate</th><th>Role</th><th>Skills</th><th>Status</th><th>Update</th></tr></thead><tbody>${apps.map(a=>`<tr><td>${esc(a.candidate)}</td><td>${esc(a.title)}</td><td>${esc(a.skills.join(', '))}</td><td>${statusPill(a.status)}</td><td><select class="field" onchange="setApplicationStatus('${a.userId}','${a.jobId}',this.value)"><option>${esc(a.status)}</option>${['Under Review','Shortlisted','Rejected','Selected'].filter(x=>x!==a.status).map(x=>`<option>${x}</option>`).join('')}</select></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Applications to your vacancies will appear here.</div>'}</div></div><div><div class="panel"><h2>Company profile</h2><p><strong>${esc(u.company||u.name)}</strong></p><p class="sub">${esc(u.district)} · Local employer</p><button class="btn btn-outline btn-sm" onclick="editProfile()">Edit profile</button></div><div class="panel"><h2>Discover candidates</h2><p class="sub">Browse sample job seekers and find relevant skills.</p><button class="btn btn-soft btn-sm" onclick="showDashSection('Candidates')">Search candidates</button></div><div class="panel"><h2>Community partnerships</h2><a href="#drives" class="link">Join local recruitment drives →</a><p><a href="#centres" class="link">Connect with training centres →</a></p></div></div></div>`)}
function centreDash(u){const own=db.coursesPublished.filter(c=>c.owner===u.email),enrs=allEnrollments().filter(e=>own.some(c=>c.id===e.courseId));return dashShell(u,`<div class="dash-welcome"><div><h1>Training centre dashboard</h1><p>Publish learning opportunities and track learner progress.</p></div><button class="btn btn-primary" onclick="courseForm()">＋ Add a course</button></div><div class="metric-grid">${metric('Published courses',own.length)}${metric('Student enrolments',enrs.length)}${metric('Learners in progress',enrs.filter(x=>x.status==='Enrolled').length)}${metric('Placements recorded',enrs.filter(x=>x.placed).length)}</div><div class="dash-grid"><div><div class="panel"><h2>Your courses</h2>${own.length?`<div class="table-wrap"><table><thead><tr><th>Course</th><th>Seats</th><th>Enrolled</th><th>Action</th></tr></thead><tbody>${own.map(c=>`<tr><td>${esc(c.name)}</td><td>${c.seats}</td><td>${enrs.filter(e=>e.courseId===c.id).length}</td><td><button class="btn btn-outline btn-sm" onclick="editCourse('${c.id}')">Edit</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Add a course to begin reaching local learners.</div>'}</div><div class="panel"><h2>Student enrolments</h2>${enrs.length?`<div class="table-wrap"><table><thead><tr><th>Learner</th><th>Course</th><th>Attendance</th><th>Progress</th><th>Performance</th><th>Placement</th></tr></thead><tbody>${enrs.map(e=>`<tr><td>${esc(e.candidate)}</td><td>${esc(e.title)}</td><td><input class="field" type="number" min="0" max="100" style="width:70px" value="${e.attendance||0}" onchange="updateEnrollment('${e.userId}','${e.courseId}','attendance',this.value)">%</td><td><select class="field" onchange="updateEnrollment('${e.userId}','${e.courseId}','status',this.value)">${['Enrolled','In progress','Completed'].map(s=>`<option ${s===e.status?'selected':''}>${s}</option>`).join('')}</select></td><td><input class="field" type="number" min="0" max="100" style="width:70px" value="${e.performance||0}" onchange="updateEnrollment('${e.userId}','${e.courseId}','performance',this.value)">%</td><td><button class="btn btn-soft btn-sm" onclick="updateEnrollment('${e.userId}','${e.courseId}','placed',true)">${e.placed?'Placed':'Record'}</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">Student enrolments will show here.</div>'}</div></div><div><div class="panel"><h2>Institute profile</h2><p><strong>${esc(u.company||u.name)}</strong></p><p class="sub">${esc(u.district)} · Training partner</p><span class="pill orange">Accreditation status: demo</span><div style="margin-top:13px"><button class="btn btn-outline btn-sm" onclick="editProfile()">Edit profile</button></div></div><div class="panel"><h2>Placement tracker</h2><p class="sub">Record learner placements for local reporting. Entries remain demo data.</p></div></div></div>`)}
function adminDash(u){const people=db.users.length,applications=allApplications(),enrs=allEnrollments();return dashShell(u,`<div class="dash-welcome"><div><h1>Administration overview</h1><p>Monitor the demonstration portal across Karnataka districts.</p></div><button class="btn btn-primary" onclick="downloadReport()">↓ Export report</button></div><div class="metric-grid">${metric('Registered users',people)}${metric('Sample job listings',db.jobs.length+db.jobsPosted.length)}${metric('Training courses',db.courses.length+db.coursesPublished.length)}${metric('Applications',applications.length)}</div><div class="dash-grid"><div><div class="panel"><h2>District-wise opportunities</h2>${districtStats().map(d=>`<div class="bar"><label>${esc(d.name)}</label><span class="bar-track"><i style="width:${Math.max(4,d.pct)}%"></i></span><b>${d.jobs}</b></div>`).join('')}</div><div class="panel"><h2>Manage user registrations</h2><div class="table-wrap"><table><thead><tr><th>Name</th><th>Role</th><th>District</th><th>Approval</th></tr></thead><tbody>${db.users.map(x=>`<tr><td>${esc(x.name)}<br><span class="tiny muted">${esc(x.email)}</span></td><td>${roleName(x.role)}</td><td>${esc(x.district||'—')}</td><td>${x.verified?'<span class="pill green">Demo approved</span>':`<button class="btn btn-soft btn-sm" onclick="approveUser('${esc(x.email)}')">Approve</button>`}</td></tr>`).join('')}</tbody></table></div></div><div class="panel"><h2>Skill demand snapshot</h2>${skillDemand().map(d=>`<div class="bar"><label>${esc(d.name)}</label><span class="bar-track"><i style="width:${d.pct}%"></i></span><b>${d.count}</b></div>`).join('')}</div></div><div><div class="panel"><h2>Registration approvals</h2><p class="sub">Approve employer and training centre demo accounts here. This is a local prototype action; no legal or government verification occurs.</p></div><div class="panel"><h2>Scheme & beneficiary tracker</h2><div class="metric-grid" style="grid-template-columns:1fr 1fr"><div><span class="tiny muted">Sample course enrolments</span><strong style="display:block;margin-top:6px;font:800 23px Manrope">${enrs.length}</strong></div><div><span class="tiny muted">Stipend verified</span><strong style="display:block;margin-top:6px;font:800 17px Manrope">Not connected</strong></div></div><a href="#schemes" class="link">View public scheme information →</a></div><div class="panel"><h2>Application statuses</h2>${['Applied','Under Review','Shortlisted','Rejected','Selected'].map(s=>`<div class="row" style="margin:9px 0"><span class="sub">${s}</span><strong>${applications.filter(a=>a.status===s).length}</strong></div>`).join('')}</div></div></div>`)}
function approveUser(email){const u=db.users.find(x=>x.email===email);if(!u||currentUser()?.role!=='admin')return;u.verified=true;save();toast(`${u.name} approved in demo portal.`);render()}
function districtStats(){return ['Bengaluru Urban','Kolar','Tumakuru','Mysuru','Chikkaballapur'].map(name=>({name,jobs:[...db.jobsPosted,...db.jobs].filter(j=>j.district===name).length,courses:[...db.coursesPublished,...db.courses].filter(c=>c.district===name).length})).map(d=>({...d,pct:Math.round(d.jobs/(db.jobs.length+db.jobsPosted.length)*100)}))}
function skillDemand(){const c={};[...db.jobs,...db.jobsPosted].forEach(j=>j.skills.forEach(s=>c[s]=(c[s]||0)+1));return Object.entries(c).sort((a,b)=>b[1]-a[1]).slice(0,6).map(([name,count])=>({name,count,pct:count*100/Math.max(...Object.values(c))}))}
function render(){route=decodeURIComponent(location.hash.slice(1).split('?')[0]||'home');const pages={home, jobs:jobsPage,courses:coursesPage,apprenticeships:apprenticeshipsPage,employers:employersPage,centres:centresPage,drives:drivesPage,schemes:schemesPage,about:aboutPage,contact:contactPage,login:loginPage,assistant:assistantPage,dashboard};document.getElementById('app').innerHTML=header()+(pages[route]||home)()+footer();if(route==='login'&&localStorage.getItem(DB)){document.querySelector('.panel')?.insertAdjacentHTML('beforeend','<div class="notice" style="margin-top:14px">Legacy demo data was found in this browser. Export it before continuing with the database migration. <button class="btn btn-outline btn-sm" onclick="exportLegacyBackup()">Download data backup</button></div>')}if(route==='dashboard'&&window.dashSection)showDashSection(window.dashSection);window.scrollTo(0,0)}
window.addEventListener('hashchange',render);
async function initializePortal(){const session=await KaushalApi.init();if(session.connected){try{db={...db,...await KaushalApi.publicData()};if(session.user){activeUser=session.user;db={...db,...await KaushalApi.load()}}if(location.hash.startsWith('#verify/')){const cert=await KaushalApi.verifyCertificate(location.hash.slice(8));db.certificates=[...(db.certificates||[]).filter(x=>x.id!==cert.id),{...cert,email:activeUser?.email}]}}catch(e){console.error(e);toast('Could not load portal data from the server.')}}render()}
document.addEventListener('DOMContentLoaded',initializePortal,{once:true});
function refreshJobs(){const el=document.querySelector('main.wrap');if(el)document.getElementById('app').innerHTML=header()+jobsPage()+footer()}
function filterCards(input,selector){const q=document.getElementById(input).value.toLowerCase();document.querySelectorAll(selector).forEach(el=>el.style.display=el.textContent.toLowerCase().includes(q)?'':'none')}
function filterDistrictCards(v,selector){document.querySelectorAll(selector).forEach(el=>el.style.display=!v||el.textContent.includes(v)?'':'none')}
function setLanguage(v){lang=v;localStorage.setItem('ks.lang',v);render();toast(`${v} interface language selected`)}
async function login(form){const f=new FormData(form);try{if(!KaushalApi.connected)throw new Error('Backend is not configured. Set up PostgreSQL, run migrations and seed demo accounts.');activeUser=await KaushalApi.login({email:String(f.get('email')).trim(),password:String(f.get('password'))});db={...db,...await KaushalApi.load()};toast(`Welcome, ${activeUser.name.split(' ')[0]}!`);go('dashboard')}catch(e){toast(e.message)}}
async function register(form){const f=new FormData(form);try{if(!KaushalApi.connected)throw new Error('Backend is not configured. Set up PostgreSQL before registering.');const details={name:String(f.get('name')).trim(),email:String(f.get('email')).trim().toLowerCase(),password:String(f.get('password')),role:String(f.get('role')),district:String(f.get('district')),phone:String(f.get('phone')||'')};if(details.password.length<12)throw new Error('Use a password with at least 12 characters.');activeUser=await KaushalApi.register(details);db={...db,...await KaushalApi.load()};toast('Account created. Welcome to KaushalSetu!');go('dashboard')}catch(e){toast(e.message)}}
async function logout(){try{if(KaushalApi.connected&&currentUser())await KaushalApi.logout()}catch(e){toast(e.message)}activeUser=null;toast('You have signed out.');go('home')}
function modal(title,body){const old=document.querySelector('.modal-backdrop');if(old)old.remove();const e=document.createElement('div');e.className='modal-backdrop';e.innerHTML=`<section class="modal"><div class="modal-head"><h2>${title}</h2><button class="close" onclick="this.closest('.modal-backdrop').remove()">×</button></div>${body}</section>`;e.addEventListener('click',ev=>{if(ev.target===e)e.remove()});document.body.appendChild(e)}
function jobDetail(id){const j=[...db.jobsPosted,...db.jobs].find(x=>x.id===id);if(!j)return;const score=scoreJob(j,currentUser());modal(esc(j.title),`<div class="sub">${esc(j.company)} · ${esc(j.district)} · ${esc(j.type||'Full time')}</div><div class="chips">${j.skills.map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><div class="rule"></div><h3>About the role</h3><p class="muted" style="font-size:13px;line-height:1.7">${esc(j.description||'Role description provided by the employer.')}</p><p><strong>Qualification:</strong> ${esc(j.education)}</p><p><strong>Experience:</strong> ${esc(j.experience)}</p><p><strong>Salary:</strong> ${esc(j.salary)}</p>${score!==null?`<div class="notice">Prototype match score: <b>${score}%</b> · (60% skills + 25% experience + 15% education). This is an illustrative rule-based estimate.</div>`:''}<button class="btn btn-primary" onclick="applyJob('${j.id}');this.closest('.modal-backdrop').remove()">Apply for this job</button>`)}
function applyJob(id){const u=currentUser();if(!u)return go('login');const j=[...db.jobsPosted,...db.jobs].find(x=>x.id===id);if(u.role!=='seeker')return toast('Sign in with a job seeker account to apply.');if(u.applications.some(a=>a.jobId===id))return toast('You have already applied for this job.');u.applications.push({jobId:id,title:j.title,company:j.company,status:'Applied',date:new Date().toLocaleDateString('en-IN')});save();toast('Application submitted successfully.');render()}
function scoreJob(j,u){if(!u||u.role!=='seeker')return null;const aliases={'ml':['machine learning'],'ai':['artificial intelligence','machine learning'],'data analysis':['data analytics','sql','excel'],'communication':['customer service'],'javascript':['js']};const req=j.skills.map(x=>x.toLowerCase()),skills=(u.skills||[]).map(x=>x.toLowerCase());const hits=req.filter(r=>skills.some(s=>s===r||s.includes(r)||r.includes(s)||(aliases[r]||[]).some(a=>s.includes(a))||(aliases[s]||[]).some(a=>r.includes(a)))).length;const skill=req.length?hits/req.length:0;const exp=j.experience==='Fresher'?(u.experience==='Fresher'?1:.65):(u.experience==='1–3 years'?.9:u.experience==='3+ years'?1:.25);const edu=/any degree|12th|puc/i.test(j.education)?1:(u.qualification||'').toLowerCase().includes(j.education.toLowerCase().split(' ')[0])?.9:.65;return Math.round(100*(.60*skill+.25*exp+.15*edu))}
function skillGap(){const u=currentUser();if(!u)return go('login');const j=[...db.jobsPosted,...db.jobs].sort((a,b)=>scoreJob(b,u)-scoreJob(a,u))[0];if(!j)return;const own=(u.skills||[]).map(x=>x.toLowerCase()),missing=j.skills.filter(s=>!own.some(a=>a===s.toLowerCase()||a.includes(s.toLowerCase())||s.toLowerCase().includes(a)));const pct=Math.round(missing.length*100/j.skills.length);const course=[...db.courses,...db.coursesPublished].find(c=>c.skills.some(s=>missing.some(m=>s.toLowerCase()===m.toLowerCase())));modal('Your skill gap roadmap',`<p class="muted">Target role: <strong>${esc(j.title)}</strong> at ${esc(j.company)}</p><div class="notice">Estimated skill gap: <strong>${pct}%</strong> · based on the listed skills available in your profile.</div><h3>Skills to build</h3><div class="chips">${(missing.length?missing:['Your skills currently cover this sample role']).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div><h3 style="margin-top:18px">Suggested learning roadmap</h3><ol class="muted" style="font-size:13px;line-height:1.8"><li>Start with ${esc(missing[0]||'a role-specific project')} fundamentals.</li><li>Practice through a small portfolio project.</li><li>Update your profile and apply to relevant local roles.</li></ol>${course?`<p>Suggested course: <strong>${esc(course.name)}</strong> · ${esc(course.centre)}</p><button class="btn btn-primary" onclick="this.closest('.modal-backdrop').remove();enroll('${course.id}')">View course & enroll</button>`:''}`)}
function enroll(id){const u=currentUser();if(!u)return go('login');if(u.role!=='seeker')return toast('Sign in with a job seeker account to enroll.');const c=[...db.coursesPublished,...db.courses].find(x=>x.id===id);if(u.enrollments.some(x=>x.courseId===id))return toast('You are already enrolled in this course.');if(c.seats<=0)return toast('This course is currently full.');c.seats--;u.enrollments.push({courseId:id,title:c.name,status:'Enrolled',date:new Date().toLocaleDateString('en-IN')});save();toast(`Enrolled in ${c.name}.`);render()}
function applyApprentice(id){const u=currentUser();if(!u)return go('login');if(u.role!=='seeker')return toast('Sign in with a job seeker account to apply.');if(u.apprenticeApps.some(x=>(typeof x==='string'?x:x.id)===id))return toast('You have already applied.');u.apprenticeApps.push({id,status:'Applied',date:new Date().toLocaleDateString('en-IN')});save();toast('Apprenticeship application recorded.');render()}
function editProfile(){const u=currentUser();if(!u)return;modal('Update profile',`<form onsubmit="event.preventDefault();saveProfile(this)"><div class="form-grid"><div class="form-group"><label>Full name</label><input class="field" name="name" required value="${esc(u.name)}"></div>${u.role!=='seeker'?`<div class="form-group"><label>Company / institute name</label><input class="field" name="company" value="${esc(u.company||'')}" required></div>`:''}<div class="form-group"><label>Phone</label><input class="field" name="phone" value="${esc(u.phone||'')}" pattern="[0-9+ -]{8,15}"></div><div class="form-group"><label>District</label><select class="field" name="district">${districtOptions(u.district)}</select></div><div class="form-group"><label>Qualification</label><input class="field" name="qualification" value="${esc(u.qualification||'')}" placeholder="e.g. BE, Diploma, PUC"></div><div class="form-group full"><label>Education details</label><input class="field" name="education" value="${esc(u.education||'')}"></div><div class="form-group full"><label>Skills (comma separated)</label><input class="field" name="skills" value="${esc((u.skills||[]).join(', '))}" placeholder="Python, SQL, Communication"></div><div class="form-group full"><label>Resume upload (PDF/DOC, max 3 MB)</label><input class="field" type="file" name="resume" accept=".pdf,.doc,.docx" onchange="analyzeResume(this)"><div id="resume-result" class="tiny muted">${u.resume?`Current file: ${esc(u.resume.name)} · profile fields were not auto-extracted`:''}</div></div></div><button class="btn btn-primary" style="margin-top:15px">Save profile</button></form>`)}
async function saveProfile(form){const u=currentUser(),f=new FormData(form);['name','phone','district','qualification','education'].forEach(k=>u[k]=String(f.get(k)||'').trim());if(u.role!=='seeker')u.company=String(f.get('company')||u.company||'').trim();u.skills=String(f.get('skills')||'').split(',').map(x=>x.trim()).filter(Boolean);const file=form.elements.resume.files[0];if(file){if(file.size>3*1024*1024)return toast('Resume must be 3 MB or smaller.');if(!KaushalApi.connected)return toast('Configure the backend before uploading a resume.');try{const out=await KaushalApi.uploadResume(file);u.resume=out.resume}catch(e){return toast(e.message)}}save();document.querySelector('.modal-backdrop').remove();toast('Profile updated.');render()}
function analyzeResume(inp){const f=inp.files[0];if(!f)return;if(f.size>3*1024*1024){inp.value='';return toast('Resume must be 3 MB or smaller.')}const result=document.getElementById('resume-result');result.innerHTML=`Selected <b>${esc(f.name)}</b> (${Math.ceil(f.size/1024)} KB). Resume parsing is simulated: add skills and education manually below. The file itself is held in this browser session only.`}
function jobForm(existing){const u=currentUser();if(!u)return go('login');const j=existing||{};modal(existing?'Edit vacancy':'Post a free job',`<form onsubmit="event.preventDefault();saveJob(this,'${j.id||''}')"><div class="form-grid"><div class="form-group full"><label>Job title</label><input class="field" name="title" required value="${esc(j.title||'')}"></div><div class="form-group"><label>District</label><select name="district" class="field">${districtOptions(j.district||u.district)}</select></div><div class="form-group"><label>Job category</label><select name="category" class="field">${['IT & Data','Manufacturing','Green Energy','Marketing','Finance','Healthcare','Customer Service','Other'].map(x=>`<option ${j.category===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group"><label>Salary range</label><input class="field" name="salary" required value="${esc(j.salary||'₹3–5 LPA')}"></div><div class="form-group"><label>Experience level</label><select name="experience" class="field"><option ${j.experience==='Fresher'?'selected':''}>Fresher</option><option ${j.experience==='1–3 years'?'selected':''}>1–3 years</option><option>3+ years</option></select></div><div class="form-group"><label>Qualification</label><input class="field" name="education" value="${esc(j.education||'Any degree')}"></div><div class="form-group"><label>Required skills (comma separated)</label><input class="field" name="skills" required value="${esc((j.skills||[]).join(', '))}"></div><div class="form-group full"><label>Description</label><textarea class="field" name="description" rows="4" required>${esc(j.description||'')}</textarea></div></div><button class="btn btn-primary" style="margin-top:14px">${existing?'Save changes':'Publish job'}</button></form>`)}
function saveJob(form,id){const u=currentUser(),f=new FormData(form),prev=db.jobsPosted.find(j=>j.id===id),job={id:id||'JP'+Date.now(),owner:u.email,company:u.company||u.name,posted:'Just posted',type:'Full time',...prev,title:f.get('title'),district:f.get('district'),category:f.get('category'),salary:f.get('salary'),min:3,max:5,experience:f.get('experience'),education:f.get('education'),skills:String(f.get('skills')).split(',').map(x=>x.trim()).filter(Boolean),description:f.get('description')};if(id)db.jobsPosted[db.jobsPosted.findIndex(x=>x.id===id)]=job;else db.jobsPosted.unshift(job);save();document.querySelector('.modal-backdrop').remove();toast(id?'Job updated.':'Job published.');render()}
function editJob(id){jobForm(db.jobsPosted.find(j=>j.id===id))}
function courseForm(existing){const u=currentUser(),c=existing||{};modal(existing?'Edit course':'Publish a course',`<form onsubmit="event.preventDefault();saveCourse(this,'${c.id||''}')"><div class="form-grid"><div class="form-group full"><label>Course name</label><input class="field" name="name" required value="${esc(c.name||'')}"></div><div class="form-group"><label>Duration</label><input class="field" name="duration" required value="${esc(c.duration||'8 weeks')}"></div><div class="form-group"><label>Eligibility</label><input class="field" name="eligibility" required value="${esc(c.eligibility||'10th pass')}"></div><div class="form-group"><label>Skills covered (comma separated)</label><input class="field" name="skills" required value="${esc((c.skills||[]).join(', '))}"></div><div class="form-group"><label>Course fees</label><input class="field" name="fees" required value="${esc(c.fees||'₹0')}"></div><div class="form-group"><label>Training mode</label><select class="field" name="mode">${['In person','Hybrid','Online'].map(x=>`<option ${c.mode===x?'selected':''}>${x}</option>`).join('')}</select></div><div class="form-group"><label>Available seats</label><input class="field" type="number" min="1" name="seats" required value="${c.seats||20}"></div><div class="form-group"><label>District</label><select class="field" name="district">${districtOptions(c.district||u.district)}</select></div><div class="form-group full"><label>Accreditation information</label><input class="field" name="accreditation" value="${esc(c.accreditation||'Demo listing · enter accreditation details')}"></div></div><button class="btn btn-primary" style="margin-top:14px">${existing?'Save course':'Publish course'}</button></form>`)}
function saveCourse(form,id){const u=currentUser(),f=new FormData(form),prev=db.coursesPublished.find(c=>c.id===id),c={id:id||'CP'+Date.now(),owner:u.email,centre:u.company||u.name,...prev,name:f.get('name'),duration:f.get('duration'),eligibility:f.get('eligibility'),skills:String(f.get('skills')).split(',').map(x=>x.trim()).filter(Boolean),fees:f.get('fees'),mode:f.get('mode'),seats:Number(f.get('seats')),district:f.get('district'),accreditation:f.get('accreditation')};if(id)db.coursesPublished[db.coursesPublished.findIndex(x=>x.id===id)]=c;else db.coursesPublished.unshift(c);save();document.querySelector('.modal-backdrop').remove();toast(id?'Course updated.':'Course published.');render()}
function editCourse(id){courseForm(db.coursesPublished.find(c=>c.id===id))}
function allApplications(){return db.users.flatMap(u=>(u.applications||[]).map(a=>({...a,candidate:u.name,userId:u.id,skills:u.skills||[],resume:u.resume} )))}
function allEnrollments(){return db.users.flatMap(u=>(u.enrollments||[]).map(e=>({...e,candidate:u.name,userId:u.id,attendance:e.attendance||0,performance:e.performance||0,placed:e.placed||false})))}
function setApplicationStatus(userId,id,status){const u=db.users.find(x=>x.id===userId);const a=u?.applications.find(x=>x.jobId===id);if(a){a.status=status;save();toast(`Application marked ${status}.`);render()}}
function updateEnrollment(userId,id,key,value){const u=db.users.find(x=>x.id===userId),e=u?.enrollments.find(x=>x.courseId===id);if(!e)return;if(key==='performance')e.performance=Math.max(0,Math.min(100,Number(value)));else if(key==='attendance')e.attendance=Math.max(0,Math.min(100,Number(value)));else if(key==='placed')e.placed=true;else e.status=value;save();toast('Learner record updated.');render()}
function showDashSection(s){window.dashSection=s;const main=document.querySelector('.dash-main');if(!main)return;const u=currentUser();const mapping=u.role==='seeker'?{'My profile':()=>editProfile(),'Applications':()=>{main.innerHTML=`<div class="dash-welcome"><div><h1>My applications</h1><p>Track every application in one place.</p></div></div><div class="panel"><div class="table-wrap"><table><thead><tr><th>Role</th><th>Employer</th><th>Applied</th><th>Status</th></tr></thead><tbody>${(u.applications||[]).map(a=>`<tr><td>${esc(a.title)}</td><td>${esc(a.company)}</td><td>${esc(a.date||'—')}</td><td>${statusPill(a.status)}</td></tr>`).join('')||'<tr><td colspan="4">No applications yet.</td></tr>'}</tbody></table></div></div>`},'Apprenticeships':()=>{const items=(u.apprenticeApps||[]).map(x=>{const id=typeof x==='string'?x:x.id,a=db.apprenticeships.find(y=>y.id===id);return a?`<div class="match"><div class="row"><strong>${esc(a.title)}</strong>${statusPill(typeof x==='string'?'Applied':x.status||'Applied')}</div><div class="sub">${esc(a.company)} · ${esc(a.district)} · ${esc(x.date||'Application recorded')}</div></div>`:''}).join('');main.innerHTML=`<div class="dash-welcome"><div><h1>Apprenticeship applications</h1><p>Track your local apprenticeship applications.</p></div></div><div class="panel">${items||'<div class="empty">No apprenticeship applications yet.</div>'}<a class="link" href="#apprenticeships">Find apprenticeships →</a></div>`},'My learning':()=>{const items=(u.enrollments||[]).map(e=>`<div class="match"><div class="row"><strong>${esc(e.title)}</strong>${statusPill(e.status)}</div><div class="sub">Enrolled ${esc(e.date||'')}</div></div>`).join('');main.innerHTML=`<div class="dash-welcome"><div><h1>My learning</h1><p>Track your course enrolments and certificates.</p></div></div><div class="panel">${items||'<div class="empty">No courses enrolled yet.</div>'}<a class="link" href="#courses">Find a course →</a></div>`},'Skill assessment':()=>skillAssessment(), 'Certificates':()=>certificatePage()}:u.role==='employer'?{'Company profile':()=>editProfile(),'Job postings':()=>jobForm(),'Applications':()=>{main.innerHTML=`<div class="dash-welcome"><div><h1>Applications</h1><p>Review and update your candidate pipeline.</p></div></div><div class="panel"><p class="sub">Use the overview table to change application status.</p><a class="link" href="#dashboard">Return to overview →</a></div>`},'Candidates':()=>candidatesPage(),'Recruitment drives':()=>go('drives')}:u.role==='centre'?{'Institute profile':()=>editProfile(),'Courses':()=>courseForm(),'Enrollments':()=>{toast(`You have ${allEnrollments().filter(e=>db.coursesPublished.some(c=>c.id===e.courseId&&c.owner===u.email)).length} enrolments.`)},'Attendance & performance':()=>toast('Update attendance and course progress in the enrolments table.'),'Placements':()=>toast('Record placements from the enrolments table.')}: {'People & partners':()=>toast(`Registered accounts: ${db.users.length}`),'Approvals':()=>toast('Demo accounts are marked as approved.'),'Jobs & courses':()=>go('jobs'),'Apprenticeships':()=>go('apprenticeships'),'Analytics & reports':()=>downloadReport(),'Schemes & benefits':()=>go('schemes')};if(mapping[s])mapping[s]()}
function candidatesPage(){const users=db.users.filter(x=>x.role==='seeker');modal('Search sample candidates',`<div class="toolbar"><input class="field" id="candidate-q" placeholder="Search by skill or district" oninput="filterCards('candidate-q','.candidate-item')"></div>${users.map(c=>`<article class="candidate-item match"><div class="row"><strong>${esc(c.name)}</strong><span class="pill">${esc(c.district||'Karnataka')}</span></div><div class="sub">${esc(c.qualification||'Qualification not added')} · ${esc(c.experience||'Experience not specified')}</div><div class="chips">${(c.skills||[]).map(s=>`<span class="chip">${esc(s)}</span>`).join('')}</div>${c.resume?`<span class="tiny muted">Resume: ${esc(c.resume.name)}</span> <button class="btn btn-outline btn-sm" onclick="downloadResume('${esc(c.id)}')">Download resume</button>`:''}<div><button class="btn btn-soft btn-sm" onclick="shortlistCandidate('${esc(c.id)}')">${(currentUser().shortlisted||[]).includes(c.id)?'✓ Shortlisted':'Shortlist candidate'}</button></div></article>`).join('')||'<p class="empty">No candidate profiles yet.</p>'}`)}
async function shortlistCandidate(id){const u=currentUser();u.shortlisted=u.shortlisted||[];if(!u.shortlisted.includes(id))u.shortlisted.push(id);try{if(KaushalApi.connected)await KaushalApi.shortlist(id);else save();toast('Candidate added to your shortlist.');candidatesPage()}catch(e){toast(e.message)}}
async function downloadResume(id){try{const blob=await KaushalApi.downloadResume(id),url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='candidate-resume';a.click();URL.revokeObjectURL(url)}catch(e){toast(e.message)}}
function skillAssessment(){const u=currentUser();const bank=[{q:'Which SQL clause filters grouped results?',a:['WHERE','HAVING','ORDER BY','JOIN'],correct:1,skill:'SQL'},{q:'Which Python library is commonly used for data frames?',a:['Pandas','Flask','Requests','Tkinter'],correct:0,skill:'Python'},{q:'What is a model trained on labelled examples called?',a:['Unsupervised learning','Supervised learning','Reinforcement only','Clustering'],correct:1,skill:'Machine Learning'}];modal('Quick skill assessment',`<p class="sub">Three sample questions · your answers stay in this browser.</p><form onsubmit="event.preventDefault();scoreAssessment(this)">${bank.map((q,i)=>`<div class="panel"><strong>${i+1}. ${q.q}</strong>${q.a.map((a,n)=>`<label style="font-weight:400;margin-top:9px"><input type="radio" name="q${i}" value="${n}" required> ${a}</label>`).join('')}</div>`).join('')}<button class="btn btn-primary">Submit assessment</button></form>`)}
function scoreAssessment(form){const vals=new FormData(form);let score=0;[0,1,2].forEach(i=>{if(Number(vals.get('q'+i))===[1,0,1][i])score++});const u=currentUser();u.assessments.push({score,total:3,date:new Date().toLocaleDateString('en-IN')});save();modal('Assessment result',`<div class="notice">You scored <strong>${score}/3</strong>. This is a short prototype quiz, not a formal certification.</div><p class="sub">Use courses and practice projects to build confidence. Assessment history has been saved in your profile.</p><button class="btn btn-primary" onclick="this.closest('.modal-backdrop').remove()">Done</button>`)}
function certificatePage(){const u=currentUser(),completed=(u.enrollments||[]).filter(e=>e.status==='Completed');const existing=db.certificates.filter(c=>c.email===u.email);const list=existing.map(c=>`<div class="match"><div class="row"><strong>${esc(c.title)}</strong><a class="link" href="#verify/${c.id}">Verify certificate →</a></div><span class="tiny muted">Demo certificate · ${esc(c.id)}</span></div>`).join('');modal('Demo certificates',`<div class="notice">Certificates generated here are demonstration records. They are not officially issued or accredited.</div>${list||'<p class="sub">No certificates generated yet.</p>'}${completed.map(e=>`<button class="btn btn-primary btn-sm" style="margin:5px" onclick="generateCertificate('${e.courseId}')">Generate ${esc(e.title)} certificate</button>`).join('')||'<p class="tiny muted">Complete a course first. Training centres can update your course progress.</p>'}`)}
async function generateCertificate(courseId){const u=currentUser(),e=u.enrollments.find(x=>x.courseId===courseId);if(!e)return toast('Course enrolment not found.');try{if(!KaushalApi.connected)throw new Error('Backend is not configured.');const cert=await KaushalApi.issueCertificate(courseId);db.certificates.push({...cert,email:u.email,name:u.name});document.querySelector('.modal-backdrop')?.remove();go('verify/'+cert.id)}catch(err){toast(err.message)}}
function verifyPage(){const id=route.split('/')[1],c=db.certificates.find(x=>x.id===id),verifyUrl=location.href,qrUrl='https://api.qrserver.com/v1/create-qr-code/?size=180x180&data='+encodeURIComponent(verifyUrl);return `${pageTitle('Certificate verification','Local demonstration lookup · no official certificate registry is connected.') }<main class="wrap">${c?`<div class="cert"><span class="pill orange">DEMO CERTIFICATE · NOT OFFICIAL</span><p class="eyebrow" style="color:#9a7b3e;margin-top:20px">KAUSHALSETU · ACADEMIC PROTOTYPE</p><h2>Certificate of Course Completion</h2><p class="muted">This demo certificate recognizes that</p><h2>${esc(c.name)}</h2><p class="muted">completed the sample training programme</p><h3>${esc(c.title)}</h3><p class="sub">Issued ${esc(c.date)} · Reference ${esc(c.id)}</p><a href="${esc(verifyUrl)}"><img src="${esc(qrUrl)}" alt="QR code linking to this certificate verification page" width="180" height="180" style="margin:12px auto;display:block" onerror="this.style.display='none';this.nextElementSibling.style.display='block'"></a><div class="cert-qr" style="display:none">Verification URL<br>${esc(verifyUrl)}</div><p class="tiny muted">QR image is generated by a third-party service when online. Demo certificate only; it is not officially issued or accredited.</p></div>`:'<div class="panel" style="max-width:600px;margin:auto;text-align:center"><h2>Certificate not found</h2><p class="sub">Check the verification reference and try again.</p></div>'}</main>`}
function sendChat(){const input=document.getElementById('chat-input'),text=input.value.trim();if(!text)return;const log=document.getElementById('chat-log');log.insertAdjacentHTML('beforeend',`<div class="bubble mine">${esc(text)}</div><div class="bubble">${esc(mockReply(text))}</div>`);input.value='';log.scrollTop=log.scrollHeight}
function quickChat(s){document.getElementById('chat-input').value=s;sendChat()}
function mockReply(s){const q=s.toLowerCase();if(/interview|prepare/.test(q))return 'Try the STAR method: describe the Situation, Task, Action and Result. Research the employer, prepare two examples from projects or training, and practise a concise introduction. For local drives, bring copies of your resume and certificates.';if(/skill|learn|gap/.test(q))return 'Start with the roles that interest you, then compare their required skills with your current profile. In this demo, your dashboard can run a skill gap analysis and suggest a sample course. Python, data analysis, communication and trade skills appear in our sample listings.';if(/apply|application|job/.test(q))return 'Open Find Jobs, filter by district and experience, and select View & apply. Sign in as a job seeker to submit your demo application and follow its status from your dashboard.';if(/course|training|iti/.test(q))return 'Explore Skill Development Courses and filter by district. Sample listings show duration, fees, eligibility, mode and seats. Enrolment is stored locally in this browser.';return 'I can help with interview preparation, job applications, course discovery and skill planning. Tell me which district and career area you are interested in. These responses use a local mock assistant, not an AI service.'}
function downloadReport(){const rows=[['District','Jobs','Courses'],...districtStats().map(x=>[x.name,x.jobs,x.courses])];const csv=rows.map(r=>r.map(x=>'"'+String(x).replaceAll('"','""')+'"').join(',')).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv'}));a.download='kaushalsetu-district-report-demo.csv';a.click();URL.revokeObjectURL(a.href);toast('Demo district report exported.');}
function exportLegacyBackup(){const raw=localStorage.getItem(DB);if(!raw)return toast('No legacy browser data found.');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([raw],{type:'application/json'}));a.download='kaushalsetu-legacy-backup.json';a.click();URL.revokeObjectURL(a.href);toast('Legacy backup downloaded. Import it after seeding the database.')}
function renderVerify(){return header()+verifyPage()+footer()}
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#verify/"]');if(a){e.preventDefault();location.hash='verify/'+a.getAttribute('href').split('/')[1]}});
// Route dispatch handles certificate verification references.
const originalRender=render;render=function(){if(location.hash.startsWith('#verify/')){route=location.hash.slice(1);document.getElementById('app').innerHTML=renderVerify();window.scrollTo(0,0);return}originalRender()};
function setLanguage(v){lang=v;localStorage.setItem('ks.lang',v);render();toast(`${v} interface language selected`)}
